<script setup lang="ts">
import { reactive,ref,watch,onMounted } from 'vue'
import { api,run,ui,upload,parse,download } from './api'
import Lanes from './Lanes.vue'
const samples=ref<any[]>([]),uploadId=ref(''),count=ref(1),mapping=ref<any[]>([{lane_id:1,role:'身份未确认'}]),settings=reactive({rotation:0,left:0,top:0,right:100,bottom:100}),preview=ref<any>(null),reference=reactive<any>({quality:'部分可辨',quality_issues:[],lanes:[]}),independent=ref(false),family=ref(''),split=ref('校准集'),quality=ref('清晰'),disputed=ref<number[]>([]),busy=ref(false)
watch(count,n=>{if(n<1||n>30)return;mapping.value=Array.from({length:n},(_,i)=>({lane_id:i+1,role:mapping.value[i]?.role??'身份未确认'}));reference.lanes=mapping.value.map(m=>({lane_id:m.lane_id,band_count:null,pattern:'无法确认',position:'无法确认',brightness:'无法确认'}))},{immediate:true})
watch([mapping,settings,uploadId],()=>{preview.value=null;independent.value=false},{deep:true})
async function load(){await run(async()=>{samples.value=await api('/teacher/evaluations');samples.value.forEach(s=>{s.consent=false;s.runs.forEach((r:any)=>{r.mismatches=parse(r.audit?.mismatch_json,[]);r.note=r.audit?.note??''})})},'')}
async function fileChanged(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(file)await run(async()=>uploadId.value=(await upload('/teacher/evaluations/image',file)).upload_id,'图片已保存，请先独立标注')}
async function prepare(){await run(async()=>preview.value=await api('/teacher/evaluations/preview',{upload_id:uploadId.value,mapping:mapping.value,settings}),'发送区域已生成')}
async function save(){await run(async()=>{await api('/teacher/evaluations',{upload_id:uploadId.value,mapping:mapping.value,settings,context_key:preview.value.context_key,reference,disputed:disputed.value,family:family.value,split:split.value,quality:quality.value,independent_consent:independent.value});uploadId.value='';preview.value=null;await load()},'参考标注已冻结保存，现在可进行模型观察')}
async function observe(s:any){busy.value=true;await run(async()=>{const r=await api(`/teacher/evaluations/${s.id}/observe`,{consent:s.consent});if(r.status!=='success')throw new Error(r.error);await load()},'模型观察已保存，参考标注保持原样');busy.value=false}
onMounted(load)
</script>
<template><h2>图像辅助观察评估</h2><p class="notice">先保存独立参考标注，再请求模型。相同原图族必须在同一集合；争议、未知和泳道错配分别记录。条带数量差不能表述为定位漏检。</p><details class="panel"><summary>添加独立参考样本</summary><label>上传已获准使用的图片<input type="file" accept="image/png,image/jpeg" @change="fileChanged"></label><template v-if="uploadId"><div class="fields"><label>原图族编号<input v-model="family" maxlength="100" placeholder="相同原图及变体使用同一编号"></label><label>评估集合<select v-model="split"><option>校准集</option><option>独立验收集</option></select></label><label>图像质量分组<select v-model="quality"><option v-for="v in ['清晰','弱带','过曝','低分辨率','其他']" :key="v">{{v}}</option></select></label><label>泳道数量<input type="number" v-model.number="count" min="1" max="30"></label><label>旋转<select v-model.number="settings.rotation"><option v-for="n in [0,90,180,270]" :key="n" :value="n">{{n}}°</option></select></label><label v-for="k in (['left','top','right','bottom'] as const)" :key="k">{{({left:'左边界',top:'上边界',right:'右边界',bottom:'下边界'})[k]}}（%）<input type="number" v-model.number="settings[k]" min="0" max="100"></label><label v-for="m in mapping" :key="m.lane_id">泳道 {{m.lane_id}} 身份<select v-model="m.role"><option v-for="v in ui.config.roles" :key="v">{{v}}</option></select></label></div><button class="secondary" @click="prepare">预览参考区域</button><template v-if="preview"><img class="gel-image" :src="preview.preview" alt="独立参考标注区域"><label>参考可读性<select v-model="reference.quality"><option v-for="v in ui.config.qualities" :key="v">{{v}}</option></select></label><div class="chips"><label class="check" v-for="v in ui.config.quality_issues" :key="v"><input type="checkbox" v-model="reference.quality_issues" :value="v">{{v}}</label></div><Lanes :lanes="reference.lanes"/><h3>参考有争议的泳道</h3><div class="chips"><label class="check" v-for="m in mapping" :key="m.lane_id"><input type="checkbox" v-model="disputed" :value="m.lane_id">泳道 {{m.lane_id}}</label></div><label class="check"><input type="checkbox" v-model="independent">我已获准使用此图，已去除身份信息，未看模型候选而独立标注；同源图片使用同一原图族。</label><button :disabled="!independent||!family" @click="save">保存独立参考标注</button></template></template></details>
<div class="section-head"><h3>已保存参考样本 · {{samples.length}} 项</h3><button class="secondary" @click="download('图像评估记录.json',samples)">导出评估记录</button></div><section v-for="s in samples" :key="s.id" class="panel"><h3>样本 #{{s.id}} · {{s.family}}</h3><p class="muted">{{s.split}} · {{s.quality}}</p><details><summary>查看已冻结的参考标注与发送区域</summary><img :src="`/api/v1/teacher/evaluations/${s.id}/preview`" class="gel-image" alt="已保存参考标注的发送区域"><p v-for="l in parse(s.reference_json).lanes" :key="l.lane_id">泳道 {{l.lane_id}}：数量 {{l.band_count??'未知'}}，{{l.pattern}}，{{l.position}}，{{l.brightness}}</p></details><label class="check"><input type="checkbox" v-model="s.consent">已核对已保存区域，同意发送匿名处理副本。</label><button :disabled="!s.consent||busy||!ui.config.vision_available" @click="observe(s)">请求模型观察</button><div v-for="r in s.runs" :key="r.id"><h4>观察 #{{r.id}} · {{parse(r.response_json).status==='success'?'已返回限定观察':'本次未完成'}}</h4><p class="muted">{{r.created_at}}</p><template v-if="parse(r.response_json).status==='success'"><p v-for="l in parse(r.response_json).observations.lanes" :key="l.lane_id">泳道 {{l.lane_id}}：数量 {{l.band_count??'未知'}}，{{l.pattern}}</p><h4>人工标记泳道错配</h4><div class="chips"><label v-for="m in parse(s.mapping_json,[])" :key="m.lane_id" class="check"><input type="checkbox" v-model="r.mismatches" :value="m.lane_id">泳道 {{m.lane_id}}</label></div><label>评估备注<textarea v-model="r.note" rows="2"></textarea></label><button class="secondary" @click="run(async()=>{await api(`/teacher/evaluations/runs/${r.id}/audit`,{mismatches:r.mismatches,note:r.note});await load()})">保存错配标记与备注</button></template></div><details v-if="s.comparisons.length"><summary>查看逐泳道比较</summary><div class="table-scroll"><table><thead><tr><th>观察版本</th><th>泳道</th><th>参考数量</th><th>AI数量</th><th>可比较</th><th>参考争议</th><th>错配标记</th></tr></thead><tbody><tr v-for="(c,i) in s.comparisons" :key="i"><td>{{c['观察版本']}}</td><td>{{c['泳道']}}</td><td>{{c['参考条带数']??'未知'}}</td><td>{{c['AI原始条带数']??'未知'}}</td><td>{{c['数量可比较']?'是':'否'}}</td><td>{{c['参考有争议']?'是':'否'}}</td><td>{{c['泳道错配人工标记']===null?'未标注':c['泳道错配人工标记']?'是':'否'}}</td></tr></tbody></table></div></details></section><p v-if="!samples.length" class="panel muted">尚无独立参考样本。添加参考标注后再进行评估。</p></template>
